-- ============================================================
-- Meloscent — Migration 002: rich blog fields
-- Adds structured-content columns used by the Discover-grade
-- "Best Summer Perfumes 2026" post, backfills slugs, seeds the post.
-- Safe to re-run.
-- Run AFTER 001_initial_schema.sql (and seed.sql if used).
-- ============================================================

ALTER TABLE blog_posts
  ADD COLUMN IF NOT EXISTS slug             text,
  ADD COLUMN IF NOT EXISTS hero_image       text,
  ADD COLUMN IF NOT EXISTS hero_alt         text,
  ADD COLUMN IF NOT EXISTS author           text,
  ADD COLUMN IF NOT EXISTS author_role      text,
  ADD COLUMN IF NOT EXISTS date_published   date,
  ADD COLUMN IF NOT EXISTS date_modified    date,
  ADD COLUMN IF NOT EXISTS tags             text[] NOT NULL DEFAULT '{}',
  ADD COLUMN IF NOT EXISTS meta_title       text,
  ADD COLUMN IF NOT EXISTS meta_description text,
  ADD COLUMN IF NOT EXISTS body             jsonb;

CREATE UNIQUE INDEX IF NOT EXISTS blog_posts_slug_idx ON blog_posts(slug);

-- ── Backfill slugs for existing posts ────────────────────────
UPDATE blog_posts SET slug = 'the-art-of-dupes' WHERE id = 1 AND slug IS NULL;
UPDATE blog_posts SET slug = 'understanding-scent-families' WHERE id = 2 AND slug IS NULL;
UPDATE blog_posts SET slug = '5-niche-perfumes-worth-every-penny' WHERE id = 3 AND slug IS NULL;
UPDATE blog_posts SET slug = 'how-to-layer-fragrances' WHERE id = 4 AND slug IS NULL;
UPDATE blog_posts SET slug = 'skin-chemistry-and-fragrance' WHERE id = 5 AND slug IS NULL;
UPDATE blog_posts SET slug = '2025-fragrance-dupes-ranked' WHERE id = 6 AND slug IS NULL;
UPDATE blog_posts SET slug = 'best-oud-dupes-2025' WHERE id = 7 AND slug IS NULL;
UPDATE blog_posts SET slug = 'top-10-alternatives-under-30' WHERE id = 8 AND slug IS NULL;

-- ── Seed the rich summer 2026 post ───────────────────────────
INSERT INTO blog_posts
  (id, slug, category, title, excerpt, gradient, read_time, content, published,
   hero_image, hero_alt, author, author_role, date_published, date_modified,
   tags, meta_title, meta_description, body)
VALUES (
  9,
  'best-summer-perfumes-2026',
  'Seasonal Edit',
  'Best Summer Perfumes 2026: Long-Lasting Scents for Heat & Humidity',
  'Heat amplifies a fragrance and humidity quietly drains it. This is our 2026 edit of summer scents built to survive both — citrus, aquatic and green compositions that stay crisp from morning commute to late dinner.',
  'linear-gradient(155deg,#e8a23a 0%,#d4762a 45%,#8a3a1a 100%)',
  '9 min read',
  '{}',
  true,
  '/blog/best-summer-perfumes-2026-hero.png',
  'An amber glass perfume bottle in warm golden-hour light beside fresh citrus and green leaves — Meloscent''s best summer perfumes 2026 edit.',
  'Sofia Avery',
  'Fragrance Editor, Meloscent',
  '2026-06-17'::date,
  '2026-06-17'::date,
  ARRAY['Summer','Seasonal','Citrus','Aquatic','Long-Lasting','Buying Guide']::text[],
  'Best Summer Perfumes 2026: Heat & Humidity Picks',
  'Our 2026 edit of the best summer perfumes — citrus, aquatic and green scents that hold up in heat and humidity, with a pick for every budget and moment.',
  '[{"type":"callout","text":"Updated for summer 2026 — re-tested in real heat and humidity, with current, widely available formulations."},{"type":"p","text":"Summer rewrites the rules of how a fragrance behaves. Heat speeds up evaporation, so a scent projects harder and burns through its top notes faster — what felt elegant in October can feel loud and short-lived in July."},{"type":"p","text":"Humidity complicates it further: damp air can mute the bright, volatile notes you actually want in the heat while dragging heavy bases into something cloying. So this list optimizes for the opposite — compositions that stay legible and fresh when it''s hot, that don''t collapse by lunchtime, and that read clean rather than heavy on warm skin."},{"type":"p","text":"I''ve leaned on citrus, aquatic and green-aromatic families here, with notes on how each one actually wears once the temperature climbs. There''s a pick for the office, for a date, for the beach, plus a budget hero and a splurge."},{"type":"tldr","title":"The quick edit","items":[{"label":"Best office-safe","text":"Jo Malone Lime Basil & Mandarin — crisp, clean, never overbearing in a meeting room."},{"label":"Best for date night","text":"Versace Eros — warm-sweet freshness with real presence after dark."},{"label":"Best budget pick","text":"Davidoff Cool Water — a 1988 classic that still over-delivers for the money."},{"label":"Best splurge","text":"Acqua di Parma Colonia — a timeless Italian citrus cologne that feels expensive because it is."},{"label":"Best unisex / beach","text":"Maison Margiela Replica Beach Walk — coconut-tinged sunscreen-and-sea nostalgia in a bottle."}]},{"type":"h2","text":"The 9 Best Summer Perfumes of 2026"},{"type":"p","text":"Ranked loosely by how reliably each one performs in heat — but every entry here earns its place. Notes are listed top → heart → base; I''ve kept descriptions to how they genuinely wear when it''s warm."},{"type":"perfume","rank":1,"name":"Acqua di Gio","brand":"Giorgio Armani","bestFor":"Best for humid climates","blurb":"The reference aquatic for a reason. That salty marine-and-citrus accord reads beautifully in sticky, humid air where heavier scents turn syrupy. It''s restrained rather than loud, which is exactly why it works in close quarters on a hot day — fresh, blue, and effortlessly summer.","notes":{"top":["Bergamot","Neroli","Marine Notes"],"mid":["Jasmine","Rosemary","Sea Notes"],"base":["Patchouli","Cedar","White Musk"]},"link":{"kind":"search","value":"Acqua di Gio","label":"Find an Acqua di Gio match in the catalog →"}},{"type":"perfume","rank":2,"name":"Lime Basil & Mandarin","brand":"Jo Malone London","bestFor":"Best office-safe unisex","blurb":"If you want to smell expensive without anyone clocking exactly what you''re wearing, this is it. Tart lime and mandarin lifted by green basil — sharp, clean and quietly polished. Cologne-style, so it sits close to the skin and won''t fill a meeting room, which in summer is a feature, not a flaw.","notes":{"top":["Lime","Mandarin","Bergamot"],"mid":["Basil","Thyme"],"base":["Vetiver","Patchouli"]},"link":{"kind":"search","value":"Lime Basil","label":"See it in the Meloscent catalog →"}},{"type":"perfume","rank":3,"name":"Replica Beach Walk","brand":"Maison Margiela","bestFor":"Best for the beach & vacation","blurb":"Pure sense-memory: warm sand, coconut sunscreen and a bergamot breeze. The heliotrope-and-musk drydown gives it a soft, skin-like warmth that the heat amplifies in the loveliest way. Genuinely unisex, and it earns its place on any vacation packing list.","notes":{"top":["Bergamot","Lemon","Pink Pepper"],"mid":["Coconut Milk","Ylang-Ylang","Heliotrope"],"base":["White Musk","Cedar","Benzoin"]},"link":{"kind":"search","value":"Beach Walk","label":"Find a Beach Walk match →"}},{"type":"perfume","rank":4,"name":"Light Blue","brand":"Dolce & Gabbana","bestFor":"Best easy everyday citrus","blurb":"The default Mediterranean summer scent for a reason — Sicilian lemon and crisp apple over a soft cedar-musk base. It leans fresh-fruity rather than sweet, and it''s almost impossible to wear wrong. Performance is moderate, so it''s best for daytime and easy reapplication.","notes":{"top":["Sicilian Citron","Apple","Cedar"],"mid":["Bamboo","Jasmine","White Rose"],"base":["Cedarwood","Amber","Musk"]},"link":{"kind":"search","value":"Light Blue","label":"Browse Light Blue alternatives →"}},{"type":"perfume","rank":5,"name":"Eros","brand":"Versace","bestFor":"Best for date night","blurb":"When you want freshness with some heat behind it after sundown. Cool mint and green apple up top, a warm tonka-vanilla glow underneath — it projects confidently and lasts well into the evening. It does skew sweet, so I''d save it for nights rather than a humid midday.","notes":{"top":["Mint","Green Apple","Lemon"],"mid":["Tonka Bean","Ambroxan","Geranium"],"base":["Vanilla","Vetiver","Cedar"]},"link":{"kind":"search","value":"Eros","label":"See Eros-style picks →"}},{"type":"perfume","rank":6,"name":"Sauvage EDT","brand":"Dior","bestFor":"Best for projection in heat","blurb":"The most-worn fresh fragrance on the planet, and the heat only makes its bergamot-and-ambroxan signature carry further. If you want to be noticed across a rooftop bar, this delivers — though that strength means a light hand in summer. The peppery-lavender opening keeps it from ever feeling sweet.","notes":{"top":["Bergamot","Pepper"],"mid":["Lavender","Pink Pepper","Vetiver"],"base":["Ambroxan","Cedar","Labdanum"]},"link":{"kind":"search","value":"Sauvage","label":"Find a Sauvage-style dupe →"}},{"type":"perfume","rank":7,"name":"L''Eau d''Issey","brand":"Issey Miyake","bestFor":"Best soft, clean aquatic","blurb":"A quieter, more transparent take on aquatic — dewy lotus and a watery floral heart that feels like cool air. It''s gentle and a little soapy in the best way, which makes it ideal for hot days when you want to smell clean and weightless rather than perfumed.","notes":{"top":["Lotus","Marine Notes","Rose Water"],"mid":["Lily","Peony","Carnation"],"base":["White Musk","Cedar","Sandalwood"]},"link":{"kind":"search","value":"L''Eau d''Issey","label":"See it in the catalog →"}},{"type":"perfume","rank":8,"name":"Cool Water","brand":"Davidoff","bestFor":"Best budget pick","blurb":"Nearly four decades old and still one of the best value-for-money fresh fragrances you can buy. Minty, lavender-bright and aquatic, it''s the blueprint a lot of pricier scents quietly borrow from. Performance is modest in heat, but at this price you can spray freely.","notes":{"top":["Mint","Lavender","Coriander"],"mid":["Geranium","Neroli","Sandalwood"],"base":["Musk","Cedar","Amber"]},"link":{"kind":"search","value":"Cool Water","label":"Browse Cool Water alternatives →"}},{"type":"perfume","rank":9,"name":"Colonia","brand":"Acqua di Parma","bestFor":"Best splurge & timeless choice","blurb":"A 1916 Italian citrus cologne that still feels modern — lemon and bergamot over lavender, rose and a refined woody-vetiver base. It''s elegant and slightly old-school in the best sense, the kind of scent that reads polished at a summer wedding. Cologne concentration means it''s fleeting, so treat it as a luxurious refresh.","notes":{"top":["Sicilian Citrus","Bergamot","Lemon"],"mid":["Lavender","Rosemary","Verbena"],"base":["Patchouli","Vetiver","Sandalwood"]},"link":{"kind":"search","value":"Colonia","label":"Find a Colonia-style pick →"}},{"type":"h2","text":"How We Picked"},{"type":"p","text":"Summer is a performance problem before it''s a taste problem. The first filter was simple: does this scent stay pleasant when skin is hot and damp? Heavy oud, dense amber and gourmand vanillas can become heady and headache-inducing in those conditions, so they sat this one out in favour of families that breathe — citrus, aquatic, green and light aromatic-fougère."},{"type":"p","text":"Then longevity. Heat burns through top notes quickly, so I weighted scents with a fresh signature that survives into the heart and a base that doesn''t turn cloying. Cologne-concentration classics like Colonia made the list on character despite shorter wear — sometimes a beautiful 90 minutes and a re-spray beats six hours of something heavy."},{"type":"p","text":"There''s also a deliberate price spread here. A great summer scent shouldn''t require a luxury budget — Cool Water proves a decades-old drugstore classic can still out-perform trend-driven releases, while Colonia earns its place for the days you want something quietly special. Most of the list sits in the affordable-to-mid range, which is the whole point: summer is the season to spray generously and reapply without overthinking it. If a fragrance here has a well-loved affordable alternative, you''ll usually find it in the Meloscent catalog too."},{"type":"p","text":"A quick word on concentration, because it matters more in summer than people expect. An eau de toilette is often the smarter buy in heat: it''s lighter, brighter and easier to wear than a dense eau de parfum that can turn heavy on warm skin. The trade-off is staying power — which is exactly why several picks here pair naturally with a midday refresh rather than a single morning spray."},{"type":"p","text":"One honest caveat: fragrance notes vary by concentration, batch and reformulation over the years, and every scent develops differently on different skin. The pyramids here describe the current, widely sold versions — but treat them as a map, not a guarantee, and test on your own skin where you can. When I wasn''t confident about a note, I left it out rather than guess."},{"type":"h2","text":"How to Make Summer Fragrance Last in Heat & Humidity"},{"type":"tips","items":[{"title":"Moisturize first","text":"Fragrance clings to hydrated skin and flashes off dry skin fast. An unscented lotion before you spray is the single easiest longevity upgrade in summer."},{"title":"Aim for pulse points — sparingly","text":"Wrists, neck and behind the ears stay warm and project well. But warmth amplifies everything in heat, so go lighter than your winter hand: one or two sprays often does more than five."},{"title":"Carry a travel spray","text":"Lighter summer scents and cologne concentrations fade faster by design. A small decant for a midday refresh beats over-applying in the morning and overwhelming everyone by noon."},{"title":"Let citrus be citrus","text":"Don''t fight a bright summer scent by layering it under something heavy. If you want more staying power, layer with a matching fresh body product rather than a competing fragrance."},{"title":"Scent clothing and hair, lightly","text":"Fragrance clings to fabric and hair far longer than it does to skin, and releases gently as you move. A light mist on a shirt collar or onto a hairbrush — never directly onto a damp scalp — can carry a summer scent through a long, hot day."}]},{"type":"p","text":"A gentle, non-medical note: if your skin is sensitive or reacts to a new fragrance, patch-test first and keep sprays off freshly shaved or broken skin — and as always, do what feels comfortable for you."},{"type":"h2","text":"Summer Fragrance FAQ"},{"type":"faq","items":[{"q":"What makes a perfume good for summer?","a":"Lightness and clarity. Fresh families — citrus, aquatic, green and light aromatics — stay legible and pleasant when heat amplifies projection, whereas dense ambers and gourmands can turn heavy. A good summer scent feels crisp on warm skin rather than suffocating."},{"q":"Do summer perfumes last as long as winter perfumes?","a":"Often not, and that''s by design. Heat speeds evaporation, and many summer scents are lighter concentrations, so they can fade faster. The fix is reapplication or a higher-concentration version rather than reaching for something heavier."},{"q":"Can I wear my winter perfume in summer?","a":"You can, but apply with a much lighter hand — heat will push a rich amber or oud far harder than you expect. One spray of a heavy scent in summer can project like four in winter, so dial it right back if you go that route."},{"q":"How does humidity affect how a fragrance smells?","a":"Humid air can mute bright top notes while making warm bases feel denser and sweeter. That''s why aquatic and citrus scents, which lean on freshness rather than weight, tend to hold up best in muggy conditions."},{"q":"Where should I apply perfume in hot weather?","a":"Pulse points like the wrists and neck still work well because warmth helps a scent project. Just use less than you would in winter — heat does a lot of the amplifying for you, so restraint reads more elegant."},{"q":"Are fresh summer scents unisex?","a":"Many of the best ones are. Citrus, aquatic and green compositions tend to sit comfortably across genders — Beach Walk, Lime Basil & Mandarin and the aquatics on this list all wear beautifully on anyone."}]},{"type":"related","title":"Related reading","items":[{"kind":"blog","value":"understanding-scent-families","label":"Understanding Scent Families: A Beginner''s Guide"},{"kind":"blog","value":"how-to-layer-fragrances","label":"How to Layer Fragrances Like a Professional Nose"},{"kind":"note","value":"Bergamot","label":"Browse bright bergamot fragrances"},{"kind":"note","value":"Vetiver","label":"Explore cooling vetiver scents"},{"kind":"search","value":"Acqua di Gio","label":"See aquatic picks in the catalog"}]}]'::jsonb
)
ON CONFLICT (id) DO NOTHING;

SELECT setval(pg_get_serial_sequence('blog_posts','id'), (SELECT MAX(id) FROM blog_posts));
